<?php
session_start(); require __DIR__.'/db.php'; if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32)); function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){header('Location:index.php');exit;}$q=$pdo->prepare('SELECT * FROM campaigns WHERE id=?');$q->execute([$id]);$campaign=$q->fetch();if(!$campaign){http_response_code(404);exit('Tangazo halijapatikana.');}
$platforms=['Facebook','Instagram','TikTok','WhatsApp','YouTube'];$types=['Organic','Paid Boost','Influencer','Poster'];$statuses=['Scheduled','Done','Cancelled'];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['csrf'],$_POST['csrf']??''))$error='Ombi si sahihi.';
 else {$name=trim($_POST['campaign_name']??'');$platform=$_POST['platform']??'';$date=$_POST['post_date']??'';$time=$_POST['post_time']??'';$cost=filter_var($_POST['cost']??0,FILTER_VALIDATE_INT);$type=$_POST['type']??'';$status=$_POST['status']??'';$notes=trim($_POST['notes']??'');
 if($name===''||!in_array($platform,$platforms,true)||!in_array($type,$types,true)||!in_array($status,$statuses,true)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!preg_match('/^\d{2}:\d{2}$/',$time)||$cost===false||$cost<0)$error='Tafadhali kagua taarifa ulizoingiza.';
 else {$u=$pdo->prepare('UPDATE campaigns SET campaign_name=?,platform=?,post_date=?,post_time=?,cost=?,type=?,status=?,notes=? WHERE id=?');$u->execute([$name,$platform,$date,$time,$cost,$type,$status,$notes,$id]);header('Location:index.php');exit;}
 }}
?><!doctype html><html lang="sw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hariri Tangazo</title><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="style.css"></head><body><header class="topbar"><div class="container headrow"><div><p class="eyebrow">RATIBA YA MATANGAZO</p><h1>Hariri Tangazo</h1><p class="subhead">Badili taarifa au hali ya tangazo.</p></div><a class="btn btn-light" href="index.php">← Dashboard</a></div></header><main class="container form-wrap"><form method="post" class="panel form-panel"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><?php if($error):?><p class="alert-error"><?=e($error)?></p><?php endif;?><label>Jina la tangazo<input name="campaign_name" maxlength="255" required value="<?=e($_POST['campaign_name']??$campaign['campaign_name'])?>"></label><div class="form-grid"><label>Jukwaa<select name="platform"><?php foreach($platforms as $p):?><option <?=($_POST['platform']??$campaign['platform'])===$p?'selected':''?>><?=e($p)?></option><?php endforeach;?></select></label><label>Aina<select name="type"><?php foreach($types as $t):?><option <?=($_POST['type']??$campaign['type'])===$t?'selected':''?>><?=e($t)?></option><?php endforeach;?></select></label><label>Tarehe<input type="date" name="post_date" required value="<?=e($_POST['post_date']??$campaign['post_date'])?>"></label><label>Muda<input type="time" name="post_time" required value="<?=e($_POST['post_time']??substr($campaign['post_time'],0,5))?>"></label><label>Gharama (TZS)<input type="number" name="cost" min="0" required value="<?=e($_POST['cost']??$campaign['cost'])?>"></label><label>Hali<select name="status"><?php foreach($statuses as $s):?><option <?=($_POST['status']??$campaign['status'])===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></label></div><label>Maelezo<textarea name="notes" rows="4" maxlength="5000"><?=e($_POST['notes']??$campaign['notes'])?></textarea></label><div class="form-actions"><button class="btn btn-primary">Hifadhi Mabadiliko</button><a class="btn btn-light" href="index.php">Ghairi</a><a class="btn btn-danger" href="delete.php?id=<?=$id?>">Futa tangazo</a></div></form></main></body></html>